// The knowledge base and its `hitld kb` tool (design part 8.5): search with glossary expansion, the
// generated index and decisions.md, staleness, links and the check that runs at merge.
//
// The notes are markdown files under kb/ in git, the source of truth (design 8.2). Their front
// matter is read with the files backend's reader, which takes data only (design 3.4), and checked
// against schemas/kb-note.schema.json. Nothing here edits a note: `kb index` writes only the
// generated files, never over a file it did not generate, and every other command reads.
//
// Generated, never notes: kb/index.md, kb/areas/<area>/index.md (the index split by area) and
// kb/decisions.md, each only when its third line is the generated mark. A file in one of those
// places without the mark is a note like any other, and `kb index` refuses to overwrite it.
//
// Agents read notes and the index, and any branch can change a note, so everything here is
// bounded: the scanners are linear, text is scanned up to SCAN_MAX characters, a note over its
// budget is not scanned for links at all, and what the generated files copy from front matter or
// the tracker is one line, bounded, with markdown and HTML escaped.

import { spawnSync } from 'node:child_process';
import { lstatSync, readdirSync, rmSync } from 'node:fs';
import { join, posix } from 'node:path';
import { parseItem } from '../tracker/files/frontmatter.mjs';
import {
  insidePath,
  isRegularFile,
  mkdirInside,
  readNoFollow,
  writeNoFollow,
} from '../tracker/files/safe.mjs';
import { policyDefaults } from '../policy/policy.mjs';
import { schemas } from '../schema/registry.mjs';

/** Where the public knowledge base lives, relative to the repository root. */
export const KB_DIR = 'kb';

/** The third line of every generated file. A file without it there is never overwritten or removed. */
export const GENERATED_MARK = '<!-- Generated by `hitld kb index`. Do not edit by hand. -->';

/** The most characters of one text that are scanned for links, glossary terms or search terms. */
export const SCAN_MAX = 65_536;

/** A glossary word longer than this, or an entry's words past the count, are ignored. */
const GLOSSARY_WORD_MAX = 64;
const GLOSSARY_WORDS_MAX = 20;
const GLOSSARY_ENTRIES_MAX = 2000;

/** The most results `kb search` returns. */
export const SEARCH_LIMIT = 20;

/**
 * A token estimate: UTF-8 bytes / 4, so text outside Latin script is not under-counted. Budgets
 * are coarse; the estimate need not be exact.
 * @param {string} text
 */
export const tokensOf = (text) => Math.ceil(Buffer.byteLength(text, 'utf8') / 4);

/** Code-unit order: the same on every machine, whatever its locale. @param {string} a @param {string} b */
const byCodeUnit = (a, b) => (a < b ? -1 : a > b ? 1 : 0);

/**
 * @typedef {object} Note
 * @property {string} path the path relative to kb/, with forward slashes
 * @property {string} text the whole file
 * @property {Record<string, any> | null} data the front matter, or null when it has none
 * @property {string} body
 * @property {string[]} errors problems with the front matter: reading it, and against the schema
 *
 * @typedef {{ kind: string, path: string, message: string }} Problem
 *
 * @typedef {object} KnowledgeBase
 * @property {string} repoRoot
 * @property {boolean} exists whether kb/ is there, as a directory
 * @property {Note[]} notes by path
 * @property {Map<string, string>} generated the generated files on disk (those with the mark), path relative to kb/ to text
 * @property {Problem[]} problems files that could not be read
 * @property {string[][]} glossary each term with its synonyms, lower-case
 * @property {string | null} defaultClassification the label of a note that has none: the
 *   repository's, as the commit guard reads it (tracker.json default_classification); null, the
 *   strictest, when not known
 *
 * @typedef {{ indexTokensMax: number, noteTokensMax: number, maxAgeUnsourced: number }} Budgets
 */

/** The budgets from a loaded policy (its kb section), or the defaults. @param {Record<string, any> | null | undefined} policy @returns {Budgets} */
export function budgetsOf(policy) {
  const kb = policy?.kb ?? policyDefaults().kb;
  return {
    indexTokensMax: kb.index_tokens_max,
    noteTokensMax: kb.note_tokens_max,
    maxAgeUnsourced: kb.max_age_unsourced,
  };
}

/** @param {string} text whether its third line is the generated mark */
export const hasMark = (text) => text.split('\n', 3)[2] === GENERATED_MARK;

/** @param {string} rel a path relative to kb/: one a generated file may take */
const generatedPlace = (rel) =>
  rel === 'index.md' || rel === 'decisions.md' || /^areas\/[^/]+\/index\.md$/.test(rel);

/**
 * Read every note under kb/. A symbolic link anywhere under kb/, hidden directories included, is
 * reported and never followed; hidden files and directories hold no notes.
 * @param {string} repoRoot
 * @param {{ defaultClassification?: string | null }} [options]
 * @returns {KnowledgeBase}
 */
export function loadKnowledgeBase(repoRoot, { defaultClassification = null } = {}) {
  const kbDir = insidePath(repoRoot, KB_DIR);
  /** @type {KnowledgeBase} */
  const kb = {
    repoRoot,
    exists: false,
    notes: [],
    generated: new Map(),
    problems: [],
    glossary: [],
    defaultClassification,
  };
  let st = null;
  try {
    st = lstatSync(kbDir);
  } catch {
    return kb;
  }
  if (!st.isDirectory()) {
    kb.problems.push({ kind: 'unreadable', path: KB_DIR, message: 'is not a directory' });
    return kb;
  }
  kb.exists = true;
  const registry = schemas();
  /** @param {string} dir @param {string} rel @param {boolean} hidden */
  const walk = (dir, rel, hidden) => {
    const entries = readdirSync(dir, { withFileTypes: true }).sort((a, b) =>
      byCodeUnit(a.name, b.name),
    );
    for (const d of entries) {
      const path = rel ? `${rel}/${d.name}` : d.name;
      const full = join(dir, d.name);
      if (d.isSymbolicLink()) {
        kb.problems.push({
          kind: 'unreadable',
          path: `${KB_DIR}/${path}`,
          message: 'is a symbolic link; the knowledge base does not follow links',
        });
        continue;
      }
      const hide = hidden || d.name.startsWith('.');
      if (d.isDirectory()) {
        walk(full, path, hide);
        continue;
      }
      if (hide || !d.name.endsWith('.md') || !isRegularFile(full)) continue;
      const text = readNoFollow(full);
      if (generatedPlace(path) && hasMark(text)) {
        kb.generated.set(path, text);
        continue;
      }
      const parsed = parseItem(text);
      const errors = [...parsed.errors];
      if (parsed.data) {
        for (const e of registry.validate('kb-note', parsed.data)) {
          errors.push(`${e.path || '(front matter)'} ${e.message}`);
        }
      }
      kb.notes.push({ path, text, data: parsed.data, body: parsed.body, errors });
    }
  };
  walk(kbDir, '', false);
  const glossary = kb.notes.find((n) => n.path === 'glossary.md');
  if (glossary) kb.glossary = parseGlossary(glossary.body);
  return kb;
}

/**
 * A finder of the next `ch` at or after a position, for positions that only grow: each call
 * resumes where the last search ended, so a scan that uses it stays linear.
 * @param {string} s @param {string} ch
 */
function nextOf(s, ch) {
  let at = -2; // -2: not searched yet; -1: none left
  return (/** @type {number} */ from) => {
    if (at === -1) return -1;
    if (at < from) at = s.indexOf(ch, from);
    return at;
  };
}

/**
 * The text with markdown links `[label](target)` removed, then parenthesized remarks: two passes,
 * each linear.
 * @param {string} s
 */
function withoutLinksAndRemarks(s) {
  /** @param {string} text @param {boolean} links */
  const pass = (text, links) => {
    const closeBracket = nextOf(text, ']');
    const closeParen = nextOf(text, ')');
    let out = '';
    let i = 0;
    while (i < text.length) {
      const c = text[i];
      if (links && c === '[') {
        const close = closeBracket(i + 1);
        if (close >= 0 && text[close + 1] === '(') {
          const end = closeParen(close + 2);
          if (end >= 0) {
            i = end + 1;
            continue;
          }
        }
      } else if (!links && c === '(') {
        const end = closeParen(i + 1);
        if (end >= 0) {
          i = end + 1;
          continue;
        }
      }
      out += c;
      i++;
    }
    return out;
  };
  return pass(pass(s, true), false);
}

/**
 * The glossary's terms: list lines of the form `- **term**: synonym, synonym`. Links and
 * parenthesized remarks on the line are not synonyms. Reads up to SCAN_MAX characters; a word over
 * 64 characters is not a term, and an entry keeps its first 20 words, so a search pattern built from
 * the glossary stays small.
 * @param {string} body
 * @returns {string[][]}
 */
export function parseGlossary(body) {
  /** @type {string[][]} */
  const out = [];
  for (const line of body.slice(0, SCAN_MAX).split('\n')) {
    const lead = line.trimStart();
    if (!/^[-*]\s/.test(lead)) continue;
    const plain = withoutLinksAndRemarks(lead.slice(2)).replace(/[*_`]/g, '');
    const colon = plain.indexOf(':');
    if (colon < 0) continue;
    const words = [plain.slice(0, colon), ...plain.slice(colon + 1).split(/[,;]/)]
      .map((w) => w.trim().toLowerCase())
      .filter((w) => w && w.length <= GLOSSARY_WORD_MAX)
      .slice(0, GLOSSARY_WORDS_MAX);
    if (words.length > 1) out.push([...new Set(words)]);
    if (out.length >= GLOSSARY_ENTRIES_MAX) break;
  }
  return out;
}

/** @param {Note} n @param {string} key @returns {string[]} */
const listOf = (n, key) => {
  const v = n.data?.[key];
  return Array.isArray(v) ? v.map(String) : typeof v === 'string' && v ? [v] : [];
};

/**
 * The notes other notes retire, as paths relative to kb/, each with the note that retires it.
 * @param {KnowledgeBase} kb @returns {Map<string, string>}
 */
export function supersededNotes(kb) {
  /** @type {Map<string, string>} */
  const out = new Map();
  for (const n of kb.notes) {
    for (const s of listOf(n, 'supersedes')) out.set(posix.normalize(s), n.path);
  }
  return out;
}

/**
 * Whether a note may be shown: in the index, in search results. Its front matter is valid, its
 * label is public (a note with none takes the repository's, design 10.3 and HITLD-626; with
 * that unknown, none is public), and no note supersedes it.
 * @param {KnowledgeBase} kb @param {Note} n @param {Map<string, string>} superseded
 */
function shown(kb, n, superseded) {
  if (!n.data || n.errors.length || superseded.has(n.path)) return false;
  return (n.data.classification ?? kb.defaultClassification) === 'public';
}

/** @param {string} s */
const escapeRegExp = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

/**
 * A search term with its glossary synonyms: every glossary entry that names the term, in either
 * place, adds its other words.
 * @param {string} term @param {string[][]} glossary
 */
export function expandTerm(term, glossary) {
  const t = term.toLowerCase();
  const words = new Set([t]);
  for (const entry of glossary) if (entry.includes(t)) entry.forEach((w) => words.add(w));
  return [...words];
}

/**
 * Search the notes (the grep+index retriever, design 8.5): each term, expanded through the
 * glossary, matches at the start of a word in the note's path, summary, areas, tags or body (its
 * first SCAN_MAX characters). Ranked by how many terms match, then by matches in the front matter
 * (weighted), then in the body; at most SEARCH_LIMIT results. Only notes the index would list are
 * searched: none above public, none superseded, none with invalid front matter.
 * @param {KnowledgeBase} kb
 * @param {{ terms: string[], area?: string, tag?: string }} q
 */
export function searchKnowledgeBase(kb, { terms, area, tag }) {
  const superseded = supersededNotes(kb);
  const groups = terms.map((t) => ({ term: t, words: expandTerm(t, kb.glossary) }));
  const results = [];
  for (const n of kb.notes) {
    if (!shown(kb, n, superseded)) continue;
    const areas = listOf(n, 'areas');
    const tags = listOf(n, 'tags');
    if (area && !areas.includes(area)) continue;
    if (tag && !tags.includes(tag)) continue;
    const head = [n.path, String(n.data?.summary ?? ''), ...areas, ...tags].join('\n');
    const body = n.body.slice(0, SCAN_MAX);
    let score = 0;
    /** @type {string[]} */
    const matched = [];
    for (const g of groups) {
      const re = new RegExp(`\\b(?:${g.words.map(escapeRegExp).join('|')})`, 'gi');
      const inHead = head.match(re)?.length ?? 0;
      const inBody = body.match(re)?.length ?? 0;
      if (!inHead && !inBody) continue;
      matched.push(g.term);
      score += 3 * inHead + Math.min(inBody, 20);
    }
    if (!matched.length) continue;
    results.push({
      path: `${KB_DIR}/${n.path}`,
      summary: n.data?.summary ?? null,
      areas,
      tags,
      matched,
      score: matched.length * 100 + score,
    });
  }
  results.sort((a, b) => b.score - a.score || byCodeUnit(a.path, b.path));
  return {
    expanded: Object.fromEntries(groups.map((g) => [g.term, g.words.filter((w) => w !== g.term)])),
    results: results.slice(0, SEARCH_LIMIT),
    total: results.length,
  };
}

/**
 * Text copied into a generated file: one line (control characters and line breaks become
 * spaces), at most `max` characters, with the characters that make markdown links, code, emphasis
 * or HTML escaped.
 * @param {string} s @param {number} max
 */
export function safeLine(s, max) {
  let t = String(s)
    .replace(/[\u0000-\u001f\u007f]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
  if (t.length > max) t = `${t.slice(0, max - 1).trimEnd()}…`;
  return t.replace(/[\\`*_[\]<>|]/g, '\\$&');
}

/** A link target that markdown reads as written. @param {string} href */
const safeHref = (href) =>
  encodeURI(href).replace(/[()]/g, (c) => `%${c.charCodeAt(0).toString(16).toUpperCase()}`);

/** @param {string} from a path relative to kb/ of the file holding the link @param {string} to */
const hrefFrom = (from, to) =>
  safeHref(posix.relative(posix.dirname(from), to) || posix.basename(to));

/**
 * The generated index files, path relative to kb/ to text. One index while it fits
 * kb.index_tokens_max; above it, a top-level index of areas (and of the notes with no area) and
 * kb/areas/<area>/index.md for each area. Only notes that may be shown are listed: a note with
 * invalid front matter (its area could name any path) is in `skipped`, and a superseded note or
 * one above public is left out (design 8.3: the public index never lists one).
 * @param {KnowledgeBase} kb @param {Budgets} budgets
 * @returns {{ files: Map<string, string>, split: boolean, tokens: number, skipped: string[] }}
 */
export function buildIndex(kb, budgets) {
  const superseded = supersededNotes(kb);
  /** @type {Map<string, Note[]>} */
  const byArea = new Map();
  /** @type {Note[]} */
  const general = [];
  /** @type {string[]} */
  const skipped = [];
  for (const n of kb.notes) {
    if (!n.data || n.errors.length) skipped.push(`${KB_DIR}/${n.path}`);
    if (!shown(kb, n, superseded)) continue;
    const first = listOf(n, 'areas')[0];
    if (!first) general.push(n);
    else byArea.set(first, [...(byArea.get(first) ?? []), n]);
  }
  const areas = [...byArea.keys()].sort(byCodeUnit);
  /** @param {string} at @param {Note} n */
  const line = (at, n) =>
    `- [${safeLine(n.path, 200)}](${hrefFrom(at, n.path)}): ${safeLine(n.data?.summary, 200)}`;
  const head = (/** @type {string} */ title) => [`# ${title}`, '', GENERATED_MARK, ''];
  /** @param {string} title @param {Note[]} notes */
  const section = (title, notes) => [
    `## ${title}`,
    '',
    ...notes.map((n) => line('index.md', n)),
    '',
  ];

  const whole = [
    ...head('Knowledge base index'),
    ...(general.length ? section('General', general) : []),
    ...areas.flatMap((a) => section(a, /** @type {Note[]} */ (byArea.get(a)))),
  ].join('\n');
  const tokens = tokensOf(whole);
  if (tokens <= budgets.indexTokensMax || areas.length < 2) {
    return { files: new Map([['index.md', whole]]), split: false, tokens, skipped };
  }
  /** @type {Map<string, string>} */
  const files = new Map();
  files.set(
    'index.md',
    [
      ...head('Knowledge base index'),
      'The index is split by area: read the index of the area you need.',
      '',
      ...(general.length ? section('General', general) : []),
      '## Areas',
      '',
      ...areas.map(
        (a) =>
          `- [${a}](${safeHref(`areas/${a}/index.md`)}): ${/** @type {Note[]} */ (byArea.get(a)).length} note(s)`,
      ),
      '',
    ].join('\n'),
  );
  for (const a of areas) {
    const at = `areas/${a}/index.md`;
    files.set(
      at,
      [
        ...head(`Knowledge base index: ${a}`),
        .../** @type {Note[]} */ (byArea.get(a)).map((n) => line(at, n)),
        '',
      ].join('\n'),
    );
  }
  return { files, split: true, tokens, skipped };
}

/**
 * @typedef {{ id: string, title: string, answer: string, answered_at?: string }} DecisionLine
 * @typedef {{ id: string, rule: string }} PrecedentLine
 */

/**
 * kb/decisions.md: the answered decisions and the active precedents, pointers only (design 8.3:
 * the knowledge base explains, the tracker records). The caller passes only public ones.
 * @param {DecisionLine[]} decisions @param {PrecedentLine[]} precedents
 */
export function buildDecisions(decisions, precedents) {
  const byNumber = (/** @type {{ id: string }} */ a, /** @type {{ id: string }} */ b) => {
    const [ka, na] = [a.id.replace(/[0-9]+$/, ''), Number(/[0-9]+$/.exec(a.id)?.[0] ?? 0)];
    const [kb, nb] = [b.id.replace(/[0-9]+$/, ''), Number(/[0-9]+$/.exec(b.id)?.[0] ?? 0)];
    return byCodeUnit(ka, kb) || na - nb;
  };
  const date = (/** @type {string | undefined} */ at) =>
    at && /^[0-9]{4}-[0-9]{2}-[0-9]{2}/.test(at) ? ` (${at.slice(0, 10)})` : '';
  return [
    '# Decisions',
    '',
    GENERATED_MARK,
    '',
    'Answered decisions and active precedents. The tracker records them; read the item or the precedent for the reasoning.',
    '',
    '## Decisions',
    '',
    ...(decisions.length
      ? [...decisions]
          .sort(byNumber)
          .map(
            (d) =>
              `- ${safeLine(d.id, 40)}${date(d.answered_at)}: ${safeLine(d.title, 200)}. Answer: ${safeLine(d.answer, 300)}`,
          )
      : ['None answered yet.']),
    '',
    '## Precedents',
    '',
    ...(precedents.length
      ? [...precedents]
          .sort(byNumber)
          .map((p) => `- ${safeLine(p.id, 40)}: ${safeLine(p.rule, 300)}`)
      : ['None active.']),
    '',
  ].join('\n');
}

/**
 * Write the generated files and remove generated index files that are no longer produced (an
 * index that was split and fits again). Only paths a generated file may take, under kb/, are
 * written; a file there without the generated mark is never overwritten (it is `refused`) or
 * removed.
 * @param {KnowledgeBase} kb @param {Map<string, string>} files
 * @returns {{ written: string[], removed: string[], refused: string[] }}
 */
export function writeGenerated(kb, files) {
  const written = [];
  const removed = [];
  const refused = [];
  for (const [rel, text] of files) {
    const target = posix.normalize(`${KB_DIR}/${rel}`);
    if (!generatedPlace(rel) || !target.startsWith(`${KB_DIR}/`) || rel.split('/').includes('..')) {
      throw new Error(`${target} is not a place for a generated file under ${KB_DIR}/`);
    }
    if (kb.generated.get(rel) === text) continue;
    const full = insidePath(kb.repoRoot, target);
    let there = false;
    try {
      lstatSync(full);
      there = true;
    } catch {
      there = false;
    }
    if (there && !kb.generated.has(rel)) {
      refused.push(target);
      continue;
    }
    mkdirInside(kb.repoRoot, posix.dirname(target));
    writeNoFollow(full, text);
    written.push(target);
  }
  for (const rel of kb.generated.keys()) {
    if (files.has(rel) || rel === 'decisions.md') continue;
    rmSync(insidePath(kb.repoRoot, `${KB_DIR}/${rel}`));
    removed.push(`${KB_DIR}/${rel}`);
  }
  return { written, removed, refused };
}

/** @param {string} cwd @param {string[]} args */
function git(cwd, args) {
  const r = spawnSync('git', args, { cwd, encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] });
  return { status: r.status, out: (r.stdout ?? '').trim(), err: (r.stderr ?? '').trim() };
}

/**
 * Notes whose sources changed since `checked_at` (design 8.5): `git diff <checked_at> HEAD --
 * <sources>` is not empty. A `checked_at` that is not a commit reachable from HEAD counts as
 * stale, and so does a sourced note with none. A note with no sources is stale
 * kb.max_age_unsourced days after its `checked` date. Superseded notes are left out. Sources git
 * cannot compare are `problems`.
 * @param {KnowledgeBase} kb @param {Budgets} budgets @param {{ now?: number }} [options]
 * @returns {{ stale: { path: string, reason: 'changed' | 'unreachable' | 'unchecked' | 'old', message: string, changed?: string[] }[], problems: Problem[] }}
 */
export function staleNotes(kb, budgets, { now = Date.now() } = {}) {
  const superseded = supersededNotes(kb);
  const stale = [];
  /** @type {Problem[]} */
  const problems = [];
  const head = git(kb.repoRoot, ['rev-parse', '--verify', '--quiet', 'HEAD']);
  for (const n of kb.notes) {
    if (!n.data || superseded.has(n.path)) continue;
    const path = `${KB_DIR}/${n.path}`;
    const sources = listOf(n, 'sources');
    const at = typeof n.data.checked_at === 'string' ? n.data.checked_at : '';
    if (sources.length) {
      if (!at) {
        stale.push({
          path,
          reason: /** @type {const} */ ('unchecked'),
          message: 'has sources but no checked_at',
        });
        continue;
      }
      const reachable =
        head.status === 0 &&
        /^[0-9a-f]{7,64}$/.test(at) &&
        git(kb.repoRoot, ['rev-parse', '--verify', '--quiet', `${at}^{commit}`]).status === 0 &&
        git(kb.repoRoot, ['merge-base', '--is-ancestor', at, 'HEAD']).status === 0;
      if (!reachable) {
        stale.push({
          path,
          reason: /** @type {const} */ ('unreachable'),
          message: `checked_at ${at} is not a commit reachable from HEAD`,
        });
        continue;
      }
      const diff = git(kb.repoRoot, [
        'diff',
        '--name-only',
        at,
        'HEAD',
        '--',
        ...sources.map((s) => `:(glob)${s}`),
      ]);
      if (diff.status !== 0) {
        problems.push({
          kind: 'stale',
          path,
          message: `its sources could not be compared: ${diff.err.split('\n')[0]}`,
        });
        continue;
      }
      if (diff.out) {
        const changed = diff.out.split('\n');
        stale.push({
          path,
          reason: /** @type {const} */ ('changed'),
          message: `stale since ${at}: ${changed.length} source file(s) changed; verify against sources`,
          changed: changed.slice(0, 20),
        });
      }
      continue;
    }
    if (!budgets.maxAgeUnsourced) continue;
    const checked = typeof n.data.checked === 'string' ? Date.parse(n.data.checked) : NaN;
    if (Number.isNaN(checked)) {
      stale.push({
        path,
        reason: /** @type {const} */ ('unchecked'),
        message: 'has no sources and no checked date',
      });
    } else if ((now - checked) / 86_400_000 > budgets.maxAgeUnsourced) {
      stale.push({
        path,
        reason: /** @type {const} */ ('old'),
        message: `has no sources and was checked ${n.data.checked}, more than ${budgets.maxAgeUnsourced} days ago`,
      });
    }
  }
  return { stale, problems };
}

/**
 * A line with its inline code spans removed, in one pass. An unclosed backtick is kept as text.
 * @param {string} line
 */
function withoutCodeSpans(line) {
  let out = '';
  let i = 0;
  for (;;) {
    const open = line.indexOf('`', i);
    if (open < 0) return out + line.slice(i);
    const close = line.indexOf('`', open + 1);
    if (close < 0) return out + line.slice(i);
    out += line.slice(i, open);
    i = close + 1;
  }
}

/**
 * The link targets in a note's body (inline links `](target)` and reference definitions
 * `[label]: target`, outside fenced code and code spans) and in its front-matter `links`, each as
 * written. Linear in the text, which is read up to SCAN_MAX characters.
 * @param {Note} n @returns {string[]}
 */
function linkTargets(n) {
  /** @type {string[]} */
  const out = [];
  /** @type {string | null} */
  let fence = null;
  for (const raw of n.body.slice(0, SCAN_MAX).split('\n')) {
    const lead = raw.trimStart();
    const marker = lead.startsWith('```') ? '```' : lead.startsWith('~~~') ? '~~~' : null;
    if (fence) {
      if (marker === fence) fence = null;
      continue;
    }
    if (marker) {
      fence = marker;
      continue;
    }
    const line = withoutCodeSpans(raw);
    // A reference definition: up to three spaces, [label]: target.
    const indent = line.length - line.trimStart().length;
    if (indent <= 3 && lead.startsWith('[')) {
      const colon = line.indexOf(']:');
      if (colon > indent + 1) {
        const target = line
          .slice(colon + 2)
          .trim()
          .split(/\s/)[0];
        if (target) out.push(target.replace(/^<|>$/g, ''));
      }
    }
    // Inline links: each "](" starts a target that ends at whitespace or ")".
    let i = 0;
    for (;;) {
      const at = line.indexOf('](', i);
      if (at < 0) break;
      let j = at + 2;
      while (line[j] === ' ') j++;
      const angle = line[j] === '<';
      if (angle) j++;
      let k = j;
      while (k < line.length && !(angle ? line[k] === '>' : /[\s)]/.test(line[k]))) k++;
      if (k > j) out.push(line.slice(j, k));
      i = Math.max(k, at + 2);
    }
  }
  return [...out, ...listOf(n, 'links')];
}

/**
 * Broken links, and links to superseded notes (design 8.5). A link is relative to the note; one
 * starting with / is relative to the repository root; a URL or an anchor alone is not checked. A
 * note over kb.note_tokens_max is not scanned: its size is already an error.
 * @param {KnowledgeBase} kb @param {Budgets} [budgets]
 * @returns {Problem[]}
 */
export function linkProblems(kb, budgets = budgetsOf(null)) {
  const superseded = supersededNotes(kb);
  /** @type {Problem[]} */
  const out = [];
  for (const n of kb.notes) {
    if (tokensOf(n.text) > budgets.noteTokensMax) continue;
    const from = `${KB_DIR}/${n.path}`;
    for (const raw of new Set(linkTargets(n))) {
      if (/^[a-z][a-z0-9+.-]*:/i.test(raw) || raw.startsWith('#')) continue;
      let target = raw.replace(/[#?].*$/, '');
      try {
        target = decodeURIComponent(target);
      } catch {
        // Left as written: a bad escape is then a broken link.
      }
      const resolved = target.startsWith('/')
        ? posix.normalize(target.slice(1))
        : posix.normalize(posix.join(posix.dirname(from), target));
      if (resolved === '..' || resolved.startsWith('../')) {
        out.push({ kind: 'broken-link', path: from, message: `${raw} leaves the repository` });
        continue;
      }
      let exists = true;
      try {
        lstatSync(join(kb.repoRoot, resolved));
      } catch {
        exists = false;
      }
      if (!exists) {
        out.push({ kind: 'broken-link', path: from, message: `${raw}: no such file` });
        continue;
      }
      const inKb = resolved.startsWith(`${KB_DIR}/`) ? resolved.slice(KB_DIR.length + 1) : null;
      const by = inKb ? superseded.get(inKb) : undefined;
      if (by && !superseded.has(n.path)) {
        out.push({
          kind: 'superseded-link',
          path: from,
          message: `${raw} is superseded by ${KB_DIR}/${by}; link to that instead`,
        });
      }
    }
  }
  return out;
}

/**
 * Everything `hitld kb check` checks (design 8.5): the front matter against its schema, the size
 * budgets, links, staleness, and whether the generated files are current.
 *
 * Errors fail the check, and the merge: a file under kb/ that cannot be read (a symbolic link), a
 * note with no or bad front matter or that supersedes itself, a note above its budget, a broken
 * link or one to a superseded note. A note above the repository's ceiling is the commit guard's to
 * refuse (design 10.3); the index leaves out any note that is not public.
 *
 * Warnings do not: a stale note, or sources git cannot compare (the curator re-verifies stale
 * notes after merges, and `checked_at` is stamped at merge), an index or decisions.md that is not
 * current (regenerated by `hitld kb index`; two branches that each change notes would otherwise
 * refuse each other), and an index over its budget even after splitting by area. The merge reads
 * only the errors, so it passes `stale: false` and `generated: false`.
 *
 * @param {KnowledgeBase} kb @param {Budgets} budgets
 * @param {{ now?: number, stale?: boolean, generated?: boolean, decisions?: { decisions: DecisionLine[], precedents: PrecedentLine[] } }} [options]
 *   decisions: what decisions.md should list; without it, decisions.md is not compared
 */
export function checkKnowledgeBase(kb, budgets, options = {}) {
  /** @type {Problem[]} */
  const errors = [...kb.problems];
  /** @type {(Problem & { reason?: string, changed?: string[] })[]} */
  const warnings = [];
  for (const n of kb.notes) {
    const path = `${KB_DIR}/${n.path}`;
    if (!n.data) errors.push({ kind: 'front-matter', path, message: 'has no front matter' });
    else for (const e of n.errors) errors.push({ kind: 'front-matter', path, message: e });
    if (listOf(n, 'supersedes').some((s) => posix.normalize(s) === n.path)) {
      errors.push({ kind: 'front-matter', path, message: 'supersedes itself' });
    }
    const tokens = tokensOf(n.text);
    if (tokens > budgets.noteTokensMax) {
      errors.push({
        kind: 'size',
        path,
        message: `is about ${tokens} tokens, over kb.note_tokens_max (${budgets.noteTokensMax}): split it into notes of one topic each`,
      });
    }
  }
  errors.push(...linkProblems(kb, budgets));
  let staleCount = 0;
  if (options.stale !== false) {
    const stale = staleNotes(kb, budgets, { now: options.now });
    for (const p of stale.problems) warnings.push(p);
    for (const s of stale.stale) warnings.push({ kind: 'stale', ...s });
    staleCount = stale.stale.length;
  }
  if (options.generated !== false) {
    const index = buildIndex(kb, budgets);
    const current = [...index.files].every(([rel, text]) => kb.generated.get(rel) === text);
    const leftover = [...kb.generated.keys()].some(
      (rel) => rel !== 'decisions.md' && !index.files.has(rel),
    );
    if (kb.notes.length && (!current || leftover)) {
      warnings.push({
        kind: 'index',
        path: `${KB_DIR}/index.md`,
        message: 'is not current with the notes; run hitld kb index',
      });
    }
    if (index.split) {
      for (const [rel, text] of index.files) {
        const t = tokensOf(text);
        if (t > budgets.indexTokensMax) {
          warnings.push({
            kind: 'index',
            path: `${KB_DIR}/${rel}`,
            message: `is about ${t} tokens, over kb.index_tokens_max (${budgets.indexTokensMax}) even after splitting by area`,
          });
        }
      }
    }
    if (options.decisions && kb.exists) {
      const want = buildDecisions(options.decisions.decisions, options.decisions.precedents);
      if (kb.generated.get('decisions.md') !== want) {
        warnings.push({
          kind: 'decisions',
          path: `${KB_DIR}/decisions.md`,
          message: 'is not current with the tracker; run hitld kb index',
        });
      }
    }
  }
  return { ok: errors.length === 0, errors, warnings, stale: staleCount };
}

/**
 * The knowledge base's errors in a checked-out tree, as the merge queue reads them (design 8.5):
 * only errors, so staleness and the generated files are not computed. Empty when there is no kb/.
 * @param {string} dir the tree's root
 * @param {Record<string, any> | null} policy main's policy, for the budgets
 * @param {string | null} defaultClassification main's tracker.json default_classification
 * @returns {string[]}
 */
export function mergeErrors(dir, policy, defaultClassification) {
  try {
    const kb = loadKnowledgeBase(dir, { defaultClassification });
    if (!kb.exists && !kb.problems.length) return [];
    return checkKnowledgeBase(kb, budgetsOf(policy), { stale: false, generated: false }).errors.map(
      (x) => `${x.path} ${x.message}`,
    );
  } catch (e) {
    return [`the knowledge base could not be read: ${/** @type {Error} */ (e).message}`];
  }
}
